<?php
require_once __DIR__.'/../includes/bootstrap.php';require_admin();$title='Advanced Store Analytics';
$start=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['start']??''))?$_GET['start']:date('Y-m-01');
$end=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['end']??''))?$_GET['end']:date('Y-m-d');
if($start>$end){$x=$start;$start=$end;$end=$x;}
$from=$start.' 00:00:00';$to=date('Y-m-d H:i:s',strtotime($end.' 23:59:59'));
$days=(int)((strtotime($end)-strtotime($start))/86400)+1;
$activeStatuses="('PENDING','CONFIRMED','PROCESSING','PACKED','DISPATCHED','OUT_FOR_DELIVERY','DELIVERED')";
$cancelled="status='CANCELLED'";
$scalar=function(string $sql,array $params=[]){global $pdo;$q=$pdo->prepare($sql);$q->execute($params);return $q->fetchColumn();};
$orders=(int)$scalar("SELECT COUNT(*) FROM orders WHERE created_at BETWEEN ? AND ?",[$from,$to]);
$gross=(float)$scalar("SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE created_at BETWEEN ? AND ? AND status IN $activeStatuses",[$from,$to]);
$cancelledValue=(float)$scalar("SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE created_at BETWEEN ? AND ? AND $cancelled",[$from,$to]);
$delivered=(int)$scalar("SELECT COUNT(*) FROM orders WHERE created_at BETWEEN ? AND ? AND status='DELIVERED'",[$from,$to]);
$units=(int)$scalar("SELECT COALESCE(SUM(oi.quantity),0) FROM order_items oi JOIN orders o ON o.order_id=oi.order_id WHERE o.created_at BETWEEN ? AND ? AND o.status IN $activeStatuses",[$from,$to]);
$cost=(float)$scalar("SELECT COALESCE(SUM(oi.quantity*COALESCE(NULLIF(oi.unit_cost,0),p.cost_price,0)),0) FROM order_items oi JOIN orders o ON o.order_id=oi.order_id JOIN products p ON p.product_id=oi.product_id WHERE o.created_at BETWEEN ? AND ? AND o.status IN $activeStatuses",[$from,$to]);
$profit=$gross-$cost;$margin=$gross>0?($profit/$gross*100):0;
$avg=$orders?($gross/$orders):0;
$returns=(int)$scalar("SELECT COUNT(*) FROM orders WHERE created_at BETWEEN ? AND ? AND status='CANCELLED'",[$from,$to]);
$customers=(int)$scalar("SELECT COUNT(DISTINCT customer_id) FROM orders WHERE created_at BETWEEN ? AND ?",[$from,$to]);
$zeroCost=(int)$scalar("SELECT COUNT(*) FROM order_items oi JOIN orders o ON o.order_id=oi.order_id JOIN products p ON p.product_id=oi.product_id WHERE o.created_at BETWEEN ? AND ? AND o.status IN $activeStatuses AND COALESCE(NULLIF(oi.unit_cost,0),p.cost_price,0)=0",[$from,$to]);
$stockValue=(float)$scalar("SELECT COALESCE(SUM(quantity_in_stock*cost_price),0) FROM products");
$rows=$pdo->prepare("SELECT DATE(o.created_at) day,COUNT(DISTINCT o.order_id) orders,COALESCE(SUM(oi.quantity),0) units,COALESCE(SUM(oi.quantity*oi.unit_price),0) revenue,COALESCE(SUM(oi.quantity*COALESCE(NULLIF(oi.unit_cost,0),p.cost_price,0)),0) cost FROM orders o JOIN order_items oi ON oi.order_id=o.order_id JOIN products p ON p.product_id=oi.product_id WHERE o.created_at BETWEEN ? AND ? AND o.status IN $activeStatuses GROUP BY DATE(o.created_at) ORDER BY day");$rows->execute([$from,$to]);$daily=$rows->fetchAll();
$topQ=$pdo->prepare("SELECT p.product_id,p.product_name,p.sku_code,COALESCE(SUM(oi.quantity),0) units,COALESCE(SUM(oi.quantity*oi.unit_price),0) revenue,COALESCE(SUM(oi.quantity*COALESCE(NULLIF(oi.unit_cost,0),p.cost_price,0)),0) cost FROM order_items oi JOIN orders o ON o.order_id=oi.order_id JOIN products p ON p.product_id=oi.product_id WHERE o.created_at BETWEEN ? AND ? AND o.status IN $activeStatuses GROUP BY p.product_id,p.product_name,p.sku_code ORDER BY units DESC,revenue DESC LIMIT 15");$topQ->execute([$from,$to]);$top=$topQ->fetchAll();
$low=$pdo->query("SELECT product_id,product_name,sku_code,quantity_in_stock,reorder_level,cost_price FROM products WHERE quantity_in_stock<=reorder_level ORDER BY quantity_in_stock ASC,product_name LIMIT 20")->fetchAll();
$slowQ=$pdo->prepare("SELECT p.product_id,p.product_name,p.quantity_in_stock,COALESCE(SUM(CASE WHEN o.status IN $activeStatuses AND o.created_at BETWEEN ? AND ? THEN oi.quantity ELSE 0 END),0) sold FROM products p LEFT JOIN order_items oi ON oi.product_id=p.product_id LEFT JOIN orders o ON o.order_id=oi.order_id GROUP BY p.product_id,p.product_name,p.quantity_in_stock ORDER BY sold ASC,p.quantity_in_stock DESC LIMIT 15");$slowQ->execute([$from,$to]);$slow=$slowQ->fetchAll();
$catQ=$pdo->prepare("SELECT COALESCE(c.name,'Uncategorised') category,COALESCE(SUM(oi.quantity),0) units,COALESCE(SUM(oi.quantity*oi.unit_price),0) revenue,COALESCE(SUM(oi.quantity*COALESCE(NULLIF(oi.unit_cost,0),p.cost_price,0)),0) cost FROM order_items oi JOIN orders o ON o.order_id=oi.order_id JOIN products p ON p.product_id=oi.product_id LEFT JOIN categories c ON c.category_id=p.category_id WHERE o.created_at BETWEEN ? AND ? AND o.status IN $activeStatuses GROUP BY c.category_id,c.name ORDER BY revenue DESC");$catQ->execute([$from,$to]);$cats=$catQ->fetchAll();
$peak=$daily;$peakDay=null;$peakRevenue=0;foreach($daily as $d){if((float)$d['revenue']>$peakRevenue){$peakRevenue=(float)$d['revenue'];$peakDay=$d['day'];}}
$peakProduct=$top[0]['product_name']??'No sales yet';
$zeroSold=(int)$scalar("SELECT COUNT(*) FROM products p LEFT JOIN order_items oi ON oi.product_id=p.product_id LEFT JOIN orders o ON o.order_id=oi.order_id AND o.created_at BETWEEN ? AND ? AND o.status IN $activeStatuses WHERE o.order_id IS NULL",[$from,$to]);
require __DIR__.'/../includes/header.php';?>
<div class="admin-layout"><aside class="admin-side"><strong>Management</strong><a href="/admin/dashboard.php">Dashboard</a><a href="/admin/stock.php">Stock control</a><a href="/admin/products.php">Products</a><a href="/admin/orders.php">Orders</a><a class="active" href="/admin/analytics.php">Analytics</a><a href="/admin/support.php">Support</a><a href="/admin/settings.php">Settings</a><a href="/admin/audit.php">Audit log</a><a href="/admin/system.php">System health</a></aside><section class="admin-main">
<div class="section-head"><div><span class="eyebrow">LIVE BUSINESS INTELLIGENCE</span><h1>Advanced analytics</h1><p>Every figure below is calculated from the live MySQL orders, order items, products, stock and transaction records.</p></div></div>
<section class="panel analytics-filter"><form method="get" class="inline-form"><label>From<input type="date" name="start" value="<?=e($start)?>"></label><label>To<input type="date" name="end" value="<?=e($end)?>"></label><button class="btn primary">Refresh statistics</button><a class="btn" href="/admin/analytics.php">Current month</a></form><p class="muted">Period: <?=e($start)?> to <?=e($end)?> · <?=$days?> day(s). Cancelled orders are excluded from sales/profit.</p></section>
<div class="stat-grid stat-grid-pro analytics-kpis"><div><small>Gross sales</small><strong><?=money($gross)?></strong><span><?=$orders?> orders</span></div><div><small>Estimated cost of goods</small><strong><?=money($cost)?></strong><span><?=$zeroCost?'Some sales have no cost recorded':'Cost data complete'?></span></div><div><small>Estimated gross profit</small><strong><?=money($profit)?></strong><span><?=number_format($margin,2)?>% margin</span></div><div><small>Units sold</small><strong><?=$units?></strong><span><?=$customers?> customers</span></div><div><small>Average order value</small><strong><?=money($avg)?></strong><span>Per order</span></div><div><small>Delivered</small><strong><?=$delivered?></strong><span><?=$returns?> cancelled</span></div><div><small>Cancelled value</small><strong><?=money($cancelledValue)?></strong><span>Not counted as sales</span></div><div><small>Inventory at cost</small><strong><?=money($stockValue)?></strong><span>Current stock</span></div></div>
<div class="analytics-two"><section class="panel"><h2>Daily sales and profit</h2><?php if(!$daily):?><p class="muted">No sales in this period.</p><?php else:?><div class="analytics-bars"><?php $max=max(1,...array_map(fn($x)=>(float)$x['revenue'],$daily));foreach($daily as $d):$h=max(4,(int)(((float)$d['revenue']/$max)*180));$dp=(float)$d['revenue']-(float)$d['cost'];?><div class="bar-col"><span title="<?=money((float)$d['revenue'])?>"><?=money((float)$d['revenue'])?></span><div class="bar" style="height:<?=$h?>px"></div><small><?=e(date('d M',strtotime($d['day'])))?></small><em><?=money($dp)?> profit</em></div><?php endforeach;?></div><?php endif;?><div class="metric-callout"><strong>Highest sales day:</strong> <?=e($peakDay??'No sales yet')?> · <?=money($peakRevenue)?></div></section>
<section class="panel"><h2>Sales health</h2><div class="health-mini"><div><b><?=$orders?></b><span>Orders</span></div><div><b><?=$units?></b><span>Units</span></div><div><b><?=number_format($margin,1)?>%</b><span>Margin</span></div><div><b><?=$zeroSold?></b><span>Products with no sales</span></div></div><p class="muted">Profit is an estimate until a purchase cost is recorded. Use Stock In to enter the latest unit cost; future orders snapshot that cost.</p></section></div>
<div class="analytics-two"><section class="panel"><h2>Top products — units, revenue, profit</h2><div class="table-wrap"><table><thead><tr><th>Product</th><th>Units</th><th>Revenue</th><th>Cost</th><th>Profit</th><th>Margin</th></tr></thead><tbody><?php foreach($top as $p):$pp=(float)$p['revenue']-(float)$p['cost'];$pm=(float)$p['revenue']>0?$pp/(float)$p['revenue']*100:0;?><tr><td><strong><?=e($p['product_name'])?></strong><br><small><?=e($p['sku_code'])?></small></td><td><?=$p['units']?></td><td><?=money((float)$p['revenue'])?></td><td><?=money((float)$p['cost'])?></td><td class="<?= $pp<0?'danger-text':'positive-text'?>"><?=money($pp)?></td><td><?=number_format($pm,1)?>%</td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><h2>Slow / non-selling products</h2><div class="compact-list"><?php foreach($slow as $p):?><div><strong><?=e($p['product_name'])?></strong><span><?=$p['sold']?> sold · <?=$p['quantity_in_stock']?> in stock</span><?php if((int)$p['sold']===0):?><span class="stock-label">NO SALES</span><?php endif;?></div><?php endforeach;?></div></section></div>
<div class="analytics-two"><section class="panel"><h2>Category performance</h2><div class="table-wrap"><table><thead><tr><th>Category</th><th>Units</th><th>Revenue</th><th>Profit</th><th>Margin</th></tr></thead><tbody><?php foreach($cats as $c):$cp=(float)$c['revenue']-(float)$c['cost'];$cm=(float)$c['revenue']>0?$cp/(float)$c['revenue']*100:0;?><tr><td><?=e($c['category'])?></td><td><?=$c['units']?></td><td><?=money((float)$c['revenue'])?></td><td><?=money($cp)?></td><td><?=number_format($cm,1)?>%</td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><h2>Inventory risk</h2><?php if(!$low):?><p class="muted">No low-stock products.</p><?php else:?><div class="compact-list"><?php foreach($low as $p):?><div><strong><?=e($p['product_name'])?></strong><span><?=$p['quantity_in_stock']?> left · reorder <?=$p['reorder_level']?> · cost <?=money((float)$p['cost_price'])?></span><a class="btn small" href="/admin/stock.php?product_id=<?=$p['product_id']?>">Adjust stock</a></div><?php endforeach;?></div><?php endif;?></section></div>
<div class="panel"><h2>Management insights</h2><div class="insight-grid"><div><b>Best seller</b><span><?=e($peakProduct)?></span></div><div><b>Peak sales day</b><span><?=e($peakDay??'No sales yet')?></span></div><div><b>Profit / loss</b><span class="<?= $profit<0?'danger-text':'positive-text'?>"><?=money($profit)?><?= $profit<0?' loss':''?></span></div><div><b>Cost data coverage</b><span><?= $zeroCost===0?'100% for this period':'Incomplete — update Stock In costs'?></span></div></div></div>
</section></div><?php require __DIR__.'/../includes/footer.php';?>
